import { describe, expect, it } from "vitest";
import { NODE_IDS, type Block, type LabSnapshot, type MiningSnapshot, type NodeId, type Transaction } from "../api/types";
import scenarios from "../test-fixtures/lab-scenarios.json";
import type { RoomState } from "./useClassroom";
import { collectGuideTransactions, deriveGuideProgress, pickPendingGuideTransaction } from "./teamGuideProgress";

// These ledger states were generated by the real Python engine, including its signed transaction and mined block.
const data = scenarios.learning as unknown as {
  initial: LabSnapshot; submitted: LabSnapshot; minedAtA: LabSnapshot; delivered: LabSnapshot;
  signed: Transaction; candidate: Block;
};
const tx = data.signed;
function room(lab = data.submitted): RoomState {
  return { teamMode: true, code: "ABCD2345", runId: "current-run", seq: 10,
    closed: false, automatic: true, activity: [], lab: structuredClone(lab),
    participants: [
      { id: "rep-b", name: "B 담당", role: "representative", team: "B", connected: true },
      { id: "observer", name: "관찰자", role: "observer", team: null, connected: true },
    ] };
}
function propagated() {
  const state = room();
  for (const node of NODE_IDS) state.lab.nodes[node].mempool = [structuredClone(tx)];
  return state;
}
function prepared(state: RoomState) {
  const job = (node: NodeId): MiningSnapshot => ({
    jobId: `job-${node}`, seq: 1, status: "paused", node, mode: "fast", attempts: 0,
    elapsedMs: 0, observationMs: 0, samples: [], block: structuredClone(data.candidate),
    message: null, nextTickInMs: null,
  });
  state.lab.race = {
    id: "race", seq: 1, status: "paused", guided: true, mode: "fast",
    enabled: { A: false, B: false, C: false }, completed: [], message: "", advance: null,
    jobs: { A: job("A"), B: job("B"), C: job("C") },
  };
  return state.lab.race;
}

describe("가이드 완료는 선택한 거래의 실제 원장 증거로 판단한다", () => {
  it("이전 확정 거래를 자동으로 선택하거나 새 실습의 완료로 표시하지 않는다", () => {
    const state = room(data.delivered);
    expect(pickPendingGuideTransaction(state)).toBeNull();
    expect(collectGuideTransactions(state)).toHaveLength(1);
    const empty = deriveGuideProgress(state, null);
    expect(empty.steps.map((step) => step.complete)).toEqual([true, true, false, false, false, false]);
    expect(empty.nextStep).toBe(2);
    expect(deriveGuideProgress(state, tx.id).steps.every((step) => step.complete)).toBe(true);
  });

  it("한 노드에 접수한 서명 거래는 거래 만들기만 완료하고 전파를 안내한다", () => {
    const state = room();
    expect(pickPendingGuideTransaction(state)).toBe(tx.id);
    const progress = deriveGuideProgress(state, tx.id);
    expect(progress.steps.map((step) => step.complete)).toEqual([true, true, true, false, false, false]);
    expect(progress.nodes.map((node) => node.status)).toEqual(["pending", "missing", "missing"]);
    expect(progress.nextAction).toContain("B·C");
    expect(progress.nextDestination).toBe("노드·블록체인");
  });

  it("연결된 대표 한 명이면 관찰자도 진행하며 끊긴 대표만 있으면 역할을 요청한다", () => {
    const state = room();
    expect(deriveGuideProgress(state, null).steps[0].complete).toBe(true);
    state.participants[0].connected = false;
    const progress = deriveGuideProgress(state, tx.id);
    expect(progress.steps[0].complete).toBe(false);
    expect(progress.nextDestination).toBe("roles");
    expect(progress.steps[2].complete).toBe(true);
  });

  it("발견 이력이나 다른 거래의 블록으로 선택한 거래의 채굴을 완료하지 않는다", () => {
    const state = propagated();
    const race = prepared(state);
    race.completed.push({ node: "A", hash: data.minedAtA.nodes.A.chain[1].hash, height: 1, attempts: 5 });
    for (const node of NODE_IDS) race.jobs[node].block.transactions = [];
    const progress = deriveGuideProgress(state, tx.id);
    expect(progress.steps[3].complete).toBe(true);
    expect(progress.steps[4].complete).toBe(false);
    expect(progress.nextAction).toContain("세 후보 준비");
  });

  it("준비·참여·실행·계산 중 안내를 현재 후보와 실행 상태에 맞춰 바꾼다", () => {
    const state = propagated();
    expect(deriveGuideProgress(state, tx.id).nextAction).toContain("세 후보 준비");
    const race = prepared(state);
    expect(deriveGuideProgress(state, tx.id).nextAction).toContain("내 채굴 참여");
    race.enabled.B = true;
    expect(deriveGuideProgress(state, tx.id).nextAction).toContain("전체 시작 / 계속");
    race.status = "running";
    expect(deriveGuideProgress(state, tx.id).nextAction).toContain("해시를 계산 중");
  });

  it("실제로 채굴한 노드와 아직 수신하지 않은 노드를 구분한다", () => {
    const progress = deriveGuideProgress(room(data.minedAtA), tx.id);
    expect(progress.nodes.map((node) => node.status)).toEqual(["confirmed", "missing", "missing"]);
    expect(progress.steps[4].complete).toBe(true);
    expect(progress.steps[5].complete).toBe(false);
    expect(progress.nextDestination).toBe("노드·블록체인");
  });

  it("한 노드 채굴은 그 노드의 담당자 참여 없이 선택된 후보의 시작을 안내한다", () => {
    const state = propagated();
    const race = prepared(state);
    race.singleNode = "A"; // The only representative in the room belongs to B.
    expect(deriveGuideProgress(state, tx.id).nextAction).toContain("노드 A의 채굴 시작 / 계속");
    race.status = "running";
    expect(deriveGuideProgress(state, tx.id).nextAction).toContain("해시를 계산 중");
    race.jobs.A.block.transactions = [];
    expect(deriveGuideProgress(state, tx.id).nextAction).toContain("선택 노드 후보 준비");
    expect(deriveGuideProgress(state, tx.id).steps[4].complete).toBe(false);
  });

  it("같은 거래가 세 노드의 같은 유효 블록에 반영돼야 결과까지 완료한다", () => {
    const progress = deriveGuideProgress(room(data.delivered), tx.id);
    expect(progress.completeCount).toBe(6);
    expect(progress.nextStep).toBeNull();
    expect(progress.nodes.every((node) => node.status === "confirmed")).toBe(true);
    expect(new Set(progress.nodes.map((node) => node.blockHash)).size).toBe(1);
  });

  it("노드별 유효 체인의 선택 블록이 갈라지면 다음 블록 채굴을 안내한다", () => {
    const state = room(data.delivered);
    state.lab.queue = [];
    // The UI consumes the engine's validation result; emulate two valid active tips with different identities.
    state.lab.nodes.C.chain[1].hash = "alternate-active-block";
    const progress = deriveGuideProgress(state, tx.id);
    expect(progress.steps[4].complete).toBe(true);
    expect(progress.steps[5].complete).toBe(false);
    expect(progress.nextDestination).toBe("채굴");
    expect(progress.nextAction).toContain("다음 블록");
  });

  it("같은 과거 거래를 가진 공통 조상만으로 서로 다른 최신 장부를 완료로 표시하지 않는다", () => {
    const state = room(data.delivered);
    for (const node of NODE_IDS) state.lab.nodes[node].chain.push({
      ...structuredClone(state.lab.nodes[node].chain[1]), height: 2,
      previousHash: state.lab.nodes[node].chain[1].hash,
      transactions: [], hash: `different-tip-${node}`,
    });
    const progress = deriveGuideProgress(state, tx.id);
    expect(new Set(progress.nodes.map((node) => node.blockHash)).size).toBe(1);
    expect(progress.steps[5].complete).toBe(false);
    expect(progress.nextDestination).toBe("노드·블록체인");
    expect(progress.nextAction).toContain("최신 블록이 다릅니다");
  });

  it("검증 실패나 같은 ID의 바뀐 내용이 있는 노드는 수신·결과 완료로 세지 않는다", () => {
    const state = room(data.delivered);
    state.lab.nodes.C.chainValidation.valid = false;
    let progress = deriveGuideProgress(state, tx.id);
    expect(progress.nodes[2].status).toBe("invalid");
    expect(progress.steps[3].complete).toBe(false);
    expect(progress.steps[5].complete).toBe(false);
    state.lab.nodes.C.chainValidation.valid = true;
    const changed = state.lab.nodes.C.chain[1].transactions.find((entry) => entry.id === tx.id)!;
    changed.outputs[0].amount += 1;
    progress = deriveGuideProgress(state, tx.id);
    expect(progress.nodes[2].status).toBe("conflict");
    expect(progress.steps[5].complete).toBe(false);
    expect(progress.nextAction).toContain("검증이 다른 노드");
  });

  it("거래 JSON의 키 순서와 다른 거래의 최근 검증 오류는 수신 증거를 바꾸지 않는다", () => {
    const state = propagated();
    state.lab.nodes.C.mempool = [Object.fromEntries(Object.entries(tx).reverse()) as unknown as Transaction];
    state.lab.nodes.B.lastValidation = { valid: false, code: "OTHER_TRANSACTION_REJECTED", message: "다른 거래 거부", steps: [] };
    expect(deriveGuideProgress(state, tx.id).steps[3].complete).toBe(true);
  });

  it("재시작 후 저장 거래의 완료 증거는 유지하고 현재 역할·전달 설정은 다시 확인한다", () => {
    const state = room(data.delivered);
    state.runId = "restarted";
    state.automatic = false;
    state.participants = [];
    const progress = deriveGuideProgress(state, tx.id);
    expect(progress.steps.map((step) => step.complete)).toEqual([false, false, true, true, true, true]);
    expect(progress.nextStep).toBe(0);
  });

  it("재구성 뒤 사라진 선택 거래를 다른 과거 거래로 바꾸거나 완료로 표시하지 않는다", () => {
    const progress = deriveGuideProgress(room(data.initial), tx.id);
    expect(progress.target).toBeNull();
    expect(progress.steps.slice(2).every((step) => !step.complete)).toBe(true);
    expect(progress.nextAction).toContain("선택한 거래가 현재 원장에 없습니다");
  });
});
